def test_no_anthropic_entry_carries_v2_input_fields(anthropic):
    offenders = {
        model_id: [f for f in V2_INPUT_FIELDS if f in entry]
        for model_id, entry in anthropic.items()
        if any(f in entry for f in V2_INPUT_FIELDS)
